Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>

using namespace std;

# define Rep(i,a,b) for(int i=a;i<=b;i++)
# define _Rep(i,a,b) for(int i=a;i>=b;i--)
# define RepG(i,u) for(int i=head[u];~i;i=e[i].next)

const int N=1e6+5;
const int mod1=998244353;
const int mod2=1e9+7;
const int base=1000000;

typedef long long ll;
typedef double db;

# define chkmax(a,b) a=max(a,b)
# define chkmin(a,b) a=min(a,b)
# define PII pair<int,int>
# define mkp make_pair

template<typename T> void read(T &x){
    x=0;int f=1;
    char c=getchar();
    for(;!isdigit(c);c=getchar())if(c=='-')f=-1;
    for(;isdigit(c);c=getchar())x=(x<<1)+(x<<3)+c-'0';
    x*=f;
}

ll n;
vector<int> v[10];
ll gg;
int sum[10];
int ans;

void dfs1(int u,int x){
    v[u].push_back(((++gg)-x+mod1)%mod1),sum[u]+=v[u].back()%mod2,sum[u]%=mod2;
    if(u==6)return;
    Rep(i,0,9)dfs1(u+1,10*x+i);
}

void dfs2(ll x){
    if(x>n)return;
    if(x*base+base-1<=n&&x*base*10>n){
        ll rk=gg;
        for(int i=0,bit=1;i<=6;i++,bit*=10){
            int mae=((rk-x*bit)%mod1+mod1)%mod1;
            int pos=lower_bound(v[i].begin(),v[i].end(),-mae+mod1)-v[i].begin();
            // printf("%d\n",pos);
            ans+=((1ll*mae*v[i].size()%mod2+sum[i])%mod2-1ll*(v[i].size()-pos)*mod1%mod2+mod2)%mod2;
            ans%=mod2;
            // printf("%d\n",ans);
            gg+=v[i].size();
        }   
        return;
    }
    ans+=(((++gg)-x)%mod1+mod1)%mod1,ans%=mod2;
    Rep(i,0,9)dfs2(x*10+i);
}

int main()
{
    # ifdef YuukiYumesaki
    freopen("testdata.in","r",stdin);
    freopen("test1.out","w",stdout);
    # endif
    read(n);
    dfs1(0,0);
    Rep(i,0,6)sort(v[i].begin(),v[i].end());
    gg=0;
    Rep(i,1,9)dfs2(i);
    printf("%d\n",ans);
    return 0;
}
</original_code>
